  function reveal(){if(!root||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}}),{root,rootMargin:'0px 0px -8% 0px'});$$('.studio-shell > *:not(.photo-hero):not(.cd-hero):not(.hf)',root).forEach((el,i)=>{el.classList.add('sr');el.style.setProperty('--sr-d',`${Math.min(i,3)*70}ms`);io.observe(el);});}
