    const radios=(k,list)=>`<div class="hf-seg">${list.map(([v,l])=>`<label><input class="hf-auto" type="radio" name="${k}" value="${esc(v)}" ${chk(k,v)}><span>${esc(l)}</span></label>`).join('')}</div>`;
    const priceList=k=>[...new Set([...PRICES,...(f[k]?[Number(f[k])]:[])])].sort((a,b)=>a-b);
