    const bbLabel=f.minBeds||f.minBaths?`${f.minBeds?f.minBeds+'+ bd':''}${f.minBeds&&f.minBaths?' · ':''}${f.minBaths?f.minBaths+'+ ba':''}`:'';
    const moreCount=['q','status','type','keyword','days','minSqft','maxSqft','minLot','maxLot','minYear','maxYear','garage','stories','hoa','view','subdivision','school','featuredOnly','openOnly','tourOnly','newOnly'].filter(k=>f[k]).length+feats.length;
