  function guideView(route){let a=guidePages[route]||guidePages['buyer-guide'];return `${heading(route)}<div class="studio-guide"><aside><span class="studio-eyebrow">A BETTER PATH FORWARD</span><strong>Every great move starts with a little clarity.</strong><p>This guide is general educational content, not financial, legal, or professional advice.</p><button data-go="contact" class="studio-btn secondary">Ask a question ↗</button></aside><main><div class="studio-section-title"><h2>The journey, <em>beautifully explained.</em></h2></div><div class="studio-timeline">${a.map(([num,title,desc])=>`<article class="studio-step"><span class="step-index">${num}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p></article>`).join('')}</div><section class="studio-guide-cta"><span>READY FOR WHAT'S NEXT?</span><h2>Let's make your next move <em>count.</em></h2><button class="studio-btn" data-go="contact">Let's connect ↗</button></section></main></div>`;}
  function calcView(){return `${heading('calculator')}<div class="studio-calculator"><form class="studio-calc-form" id="studioCalcForm"><div class="studio-section-title"><h2>Make the numbers <em>make sense.</em></h2></div>${[["price","HOME PRICE",850000,250000,4000000,25000],["down","DOWN PAYMENT (%)",20,0,50,1],["rate","INTEREST RATE (%)",6.5,1,12,.1],["years","LOAN TERM (YEARS)",30,10,30,5],["tax","PROPERTY TAX RATE (%)",.65,0,3,.05],["insurance","HOME INSURANCE / YEAR",2400,0,12000,100]].map(([n,l,v,min,max,step])=>`<div class="studio-range"><div class="studio-range-top"><label for="c-${n}">${l}</label><strong id="o-${n}">${['price','insurance'].includes(n)?usd(v):v+(n==='years'?' years':'%')}</strong></div><input id="c-${n}" name="${n}" type="range" min="${min}" max="${max}" step="${step}" value="${v}" aria-label="${l}"></div>`).join('')}</form><div class="studio-calculator-results"><span class="calc-label">ESTIMATED MONTHLY PAYMENT</span><div class="calc-total" id="calcTotal">$0 <small>/ MO</small></div><div class="studio-pie"><span>YOUR PLAN</span></div><div class="studio-breakdown"><span><i></i> PRINCIPAL + INTEREST <b id="calcPI">—</b></span><span><i></i> TAXES <b id="calcTax">—</b></span><span><i></i> INSURANCE <b id="calcInsurance">—</b></span></div><p class="studio-calc-disclaimer">Illustrative calculations only. Excludes mortgage insurance, HOA fees, closing costs, utilities and other expenses. Rates and taxes vary. Not a lending offer or quote.</p><button class="studio-btn secondary" data-go="search">Explore homes ↗</button></div></div>`;}
  function alertsView(){const all=MockAPI.getAlerts();return `${heading('alerts')}<div class="studio-form-feature"><div class="studio-form-story"><span class="mini">NEVER MISS A POSSIBILITY</span><h2>Stay close to <em>what moves you.</em></h2><p>Choose your preferred community, budget, and frequency. The alert is saved to the database.</p><div class="studio-note-3d"></div></div><form id="studioAlertForm" class="studio-form-body"><h3>Create a listing alert</h3><div class="studio-field-grid cols-2">${field('email','EMAIL *','<input type="email" required placeholder="you@example.com">')}${field('name','NAME','<input placeholder="Your name">')}${field('city','COMMUNITY',`<select>${optionCity()}</select>`)}${field('type','PROPERTY TYPE',`<select><option value="">Any type</option>${TYPES.map(v=>`<option>${v}</option>`).join('')}</select>`)}${field('minPrice','MIN PRICE',`<select><option value="">No min</option>${PRICES.map(v=>`<option value="${v}">${usd(v)}</option>`).join('')}</select>`)}${field('maxPrice','MAX PRICE',`<select><option value="">No max</option>${PRICES.map(v=>`<option value="${v}">${usd(v)}</option>`).join('')}</select>`)}${field('minBeds','BEDS',`<select><option value="">Any</option>${[1,2,3,4,5].map(v=>`<option value="${v}">${v}+</option>`).join('')}</select>`)}${field('minBaths','BATHS',`<select><option value="">Any</option>${[1,2,3,4,5].map(v=>`<option value="${v}">${v}+</option>`).join('')}</select>`)}${field('frequency','FREQUENCY','<select><option>Instant</option><option>Daily</option><option>Weekly</option></select>')}</div><label class="valuation-consent"><input type="checkbox" name="openHouses"> Also tell me about open houses that match</label><button class="studio-btn" type="submit">Save alert ↗</button><p class="studio-form-note">Saved to the database.</p><div id="studioFormStatus" role="status"></div></form></div>${all.length?`<div class="studio-section-title"><h2>Your saved <em>alerts.</em></h2></div><div class="studio-storage-grid">${all.map(a=>`<div class="studio-card padded"><small>${esc(a.frequency)} · ${esc(a.city||'All communities')}</small><h3>${esc(a.email)}</h3><p>${a.type||'Any type'} · ${a.minPrice?usd(a.minPrice):'No min'} – ${a.maxPrice?usd(a.maxPrice):'no max'}${a.minBeds?` · ${a.minBeds}+ beds`:''}${a.minBaths?` · ${a.minBaths}+ baths`:''}</p><button class="studio-btn secondary" data-action="toggle-alert" data-id="${a.id}">${a.active?'Pause alert':'Resume alert'}</button> <span class="studio-alert-active">${a.active?'ACTIVE':'PAUSED'}</span></div>`).join('')}</div>`:''}`;}
  function organizerView(){let favorites=MockAPI.listings.filter(h=>fav().includes(h.id)),saved=MockAPI.getSavedSearches(),alerts=MockAPI.getAlerts();return `${heading('organizer')}<div class="studio-stat-bar"><div><strong>${favorites.length}</strong><span>FAVORITE HOMES</span></div><div><strong>${saved.length}</strong><span>SAVED SEARCHES</span></div><div><strong>${alerts.length}</strong><span>LISTING ALERTS</span></div></div><div class="studio-section-title"><h2>Homes you've <em>saved.</em></h2><button data-go="search">Find more homes ↗</button></div><div class="studio-listing-grid">${favorites.length?cards(favorites):'<div class="studio-empty"><span>♡</span><h3>Your collection begins here.</h3><p>Tap the heart on a home to save it.</p><button class="studio-btn" data-go="search">Discover homes ↗</button></div>'}</div><div class="studio-storage-grid"><section class="studio-card padded"><h3>Saved searches</h3>${saved.length?saved.map(s=>`<div class="studio-storage-item"><div><strong>${esc(s.city||'All communities')} · ${s.minBeds?`${s.minBeds}+ beds`:'Any beds'}</strong><p>${s.maxPrice?'Up to '+usd(s.maxPrice):'Any price'}</p></div><button class="studio-btn secondary" data-action="apply-saved" data-id="${s.id}">Open ↗</button><button class="studio-delete" data-action="delete-search" data-id="${s.id}" aria-label="Delete saved search">×</button></div>`).join(''):'<p class="studio-empty-mini">No saved searches yet. Save a search from the property page to revisit it later.</p>'}<button class="studio-btn secondary" data-go="advanced">Explore searches ↗</button></section><section class="studio-card padded"><h3>Your email alerts</h3>${alerts.length?alerts.map(a=>`<div class="studio-storage-item"><div><strong>${esc(a.city||'All communities')}</strong><p>${esc(a.frequency)} · ${a.active?'Active':'Paused'}</p></div><button class="studio-btn secondary" data-action="toggle-alert" data-id="${a.id}">${a.active?'Pause':'Resume'}</button></div>`).join(''):'<p class="studio-empty-mini">Create a listing alert and it is saved to the database.</p>'}<button class="studio-btn secondary" data-go="alerts">Manage alerts ↗</button></section></div>`;}
  function blogView(){return `${heading('blog')}<div class="studio-journal-grid">${articleOrder.map(i=>[articles[i],i]).map(([a,i])=>`<button class="studio-journal-card" data-article="${i}"><span class="studio-journal-art">${articleArt[i]}</span><span class="studio-journal-text"><small>${a.category} · ${a.read}</small><strong>${esc(a.title)}</strong><span>READ THE STORY ↗</span></span></button>`).join('')}</div>`;}
  function articleView(){let a=articles[Number(state.params.article)||0]||articles[0];return `<div class="studio-detail-breadcrumb"><button data-go="blog">← All stories</button><span> / &nbsp; ${esc(a.category)}</span></div><article class="studio-article"><span class="studio-eyebrow">${a.category} · ${a.read}</span><h1>${esc(a.title)}</h1><div class="studio-article-cover">${articleArt[articles.indexOf(a)]}</div>${a.body.map((p,i)=>`<p>${esc(p)}</p>${i===0?'<h2>What matters most?</h2>':''}`).join('')}<div class="studio-guide-cta"><h2>Make your next move <em>extraordinary.</em></h2><button class="studio-btn" data-go="communities">Explore communities ↗</button></div></article>`;}
  function aboutAgent(){return `${heading('about-agent')}<section class="studio-agent-profile"><div class="studio-agent-portrait"><img src="assets/janardhan-vangala.webp" alt="Portrait of Janardhan Vangala" loading="lazy"></div><div><span class="studio-eyebrow">SOS REALTY GROUP LLC · YOUR NEVADA AGENT</span><h2>Local guidance.<br><em>Personal attention.</em></h2><p>Janardhan Vangala works with buyers, sellers and investors in Las Vegas, Henderson, North Las Vegas and Boulder City. He brings a steady, informed approach to real estate decisions: understand your needs, lay out the available options and help with each step through closing.</p><p>Whether your question is about a neighborhood, pricing a property or qualifying for an FHA or VA assumable loan, Janardhan can help you explore the next step.</p><img src="assets/sos-realty-logo.png" class="studio-agent-logo" alt="SOS Realty Group logo"><div class="studio-actions"><a class="studio-btn" href="tel:+17022151838">Call (702) 215-1838 ↗</a><button class="studio-btn secondary" data-go="contact">Send a message ↗</button><a class="studio-btn secondary" href="mailto:realtorjanardhan@gmail.com">Email Janardhan ↗</a></div><div class="studio-agent-address">SOS Realty Group LLC · 3450 E. Russell Rd, Suite 209 · Las Vegas, NV 89120 · Brokerage License B.143998</div></div></section><div class="studio-section-title"><h2>How Janardhan <em>works.</em></h2></div><div class="cd-why-grid three">${[['Clear advice','Pricing, timing and financing options explained plainly, so you can decide with confidence.'],['Valley-wide reach','Las Vegas, Henderson, North Las Vegas and Boulder City, plus the areas in between.'],['Creative financing','Help finding and qualifying for homes with assumable FHA and VA loans.']].map(([t,d],i)=>`<article><span>0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><div class="studio-section-title"><h2>Explore the <em>communities.</em></h2></div><div class="studio-community-grid">${themedCommunityCards()}</div>`;}
  const assumableFaqs=[['What is an assumable mortgage?','It is an existing home loan that a buyer can take over from the seller. The buyer keeps the seller’s interest rate, remaining balance and remaining term, so when the existing rate is lower than today’s rates, the monthly payment can be lower, too.'],['Which loans are usually assumable?','FHA, VA and USDA loans are generally assumable with the servicer’s approval. Most conventional loans include a due-on-sale clause, so they usually cannot be assumed.'],['Do I have to qualify to assume a loan?','Yes. The loan servicer reviews your credit, income and debts, much like a new loan, so it helps to gather your documents before you make an offer.'],['How do I pay the difference between the price and the loan balance?','You cover that gap at closing, either in cash or with a second loan. Because the gap can be large, Janardhan will help you run the numbers before you tour.'],['Do I need to be a veteran to assume a VA loan?','No. A non-veteran can often assume a VA loan with servicer approval. However, the seller’s VA entitlement may stay tied to the loan unless a qualified veteran buyer substitutes their own, so sellers should understand that trade-off.'],['How long does an assumption take?','Assumptions usually take longer than a standard closing, because the servicer must review and approve the buyer. Plan for extra time and keep in close touch with the servicer.'],['Where can I find assumable homes for sale in Las Vegas?','Start with the listings on this page. Janardhan tracks listings that note an assumable loan across Las Vegas, Henderson, North Las Vegas and Boulder City.']];
  function assumableView(){return `${heading('assumable')}<div class="studio-pillbar as-actions"><button class="studio-btn" data-jump="as-list">Browse assumable homes ↗</button><button class="studio-btn secondary" data-go="contact">Talk with Janardhan</button><button class="studio-btn secondary" data-jump="as-faq">Assumable loan questions</button></div>
    <div class="cd-why-grid three as-steps">${[['Find the right listing','Janardhan flags homes whose sellers have an assumable FHA, VA or USDA loan.'],['Run the numbers','Compare the assumed payment with a new loan, and plan for the equity gap.'],['Qualify with the servicer','The loan servicer reviews your credit and income, then approves the assumption.']].map(([t,d],i)=>`<article><span>STEP 0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>
    <div class="assumable-explainer"><div><span class="studio-eyebrow">A SMARTER WAY TO BUY</span><h2>What is an <em>assumable loan?</em></h2><p>Some existing FHA and VA mortgages can be transferred from seller to a qualified buyer, subject to the program rules and the loan servicer's approval. If an existing rate is lower than the rate on a new loan, the monthly principal and interest may be lower.</p><p><strong>Important:</strong> The buyer must also cover the difference between the purchase price and the outstanding loan balance (the equity gap), using cash or other financing. Qualification, release of liability, fees, and timing must all be checked with the loan servicer.</p><button class="studio-btn secondary" data-go="contact">Ask Janardhan about assumptions ↗</button></div><div class="assumable-diagram" aria-hidden="true"><span>EXISTING MORTGAGE</span><div class="assumable-diagram-disc">3.0<small>% EXAMPLE</small></div><div class="assumable-diagram-line"></div><strong>POTENTIAL RATE ADVANTAGE</strong></div></div>
    <div class="studio-section-title"><h2>Try an <em>assumption estimate.</em></h2><span>EDUCATIONAL EXAMPLE</span></div>
    <div class="studio-calculator assumable-calculator"><form id="studioAssumeForm" class="studio-calc-form">
      ${[['price','PURCHASE PRICE',600000,250000,1600000,10000],['balance','EXISTING LOAN BALANCE',350000,100000,1000000,10000],['rate','EXISTING LOAN RATE (%)',3,1,9,.1],['years','YEARS REMAINING',25,5,30,1],['market','COMPARISON RATE (%)',6.5,2,12,.1]].map(([k,label,val,min,max,step])=>`<div class="studio-range"><div class="studio-range-top"><label for="a-${k}">${label}</label><strong id="a-o-${k}">${k==='price'||k==='balance'?usd(val):k==='years'?val+' years':val+'%'}</strong></div><input id="a-${k}" name="${k}" type="range" value="${val}" min="${min}" max="${max}" step="${step}"></div>`).join('')}
    </form><div class="studio-calculator-results assumable-results"><span class="calc-label">ESTIMATED EXISTING LOAN PAYMENT</span><strong class="calc-total" id="assumePayment">—</strong><p>Monthly principal & interest only (on the outstanding balance)</p><div class="property-fact-row"><span>Same balance at comparison rate</span><strong id="assumeMarket">—</strong></div><div class="property-fact-row"><span>Illustrative monthly difference</span><strong id="assumeDifference">—</strong></div><div class="property-fact-row"><span>Purchase price less existing balance</span><strong id="assumeGap">—</strong></div><p class="studio-form-note">Comparative amortization assumes the same remaining term and loan balance. This is not a verified loan, rate quote, funding plan or affordability estimate. The equity gap may require significant additional financing, and taxes/insurance/HOA/fees are excluded.</p></div></div>
    <div class="studio-section-title" id="as-list"><h2>Assumable homes for sale <em>today.</em></h2><button class="studio-btn" data-action="assumable-report">Open the full assumable report ↗</button></div><p class="studio-disclaimer">Homes come from the mock Trestle feed. A home is assumable only when Assumable Data has a row for it.</p><div class="studio-listing-grid">${cards(MockAPI.listings.filter(h=>h.assumable))}</div>
    <section class="cd-faq" id="as-faq"><div><span class="studio-eyebrow">ASSUMABLE LOAN QUESTIONS</span><h2>Every assumption is <em>a little different.</em></h2><p>Janardhan is happy to walk through yours.</p><button class="studio-btn" data-go="contact">Ask Janardhan ↗</button></div>${faqList(assumableFaqs)}</section>`;}
